function jumpSearch(a, target) {
  const n = a.length;
  const step = Math.floor(Math.sqrt(n));
  let prev = 0, curr = step;
  while (curr < n && a[Math.min(curr, n) - 1] < target) {
    prev = curr;
    curr += step;
  }
  for (let i = prev; i < Math.min(curr, n); i++) {
    if (a[i] === target) return i;
  }
  return -1;
}

