import math

def jump_search(a, target):
    n = len(a)
    step = int(math.sqrt(n))
    prev = 0
    while prev < n and a[min(prev + step, n) - 1] < target:
        prev += step
    for i in range(prev, min(prev + step, n)):
        if a[i] == target:
            return i
    return -1

